// pool: nr_hugepages = 8, Hugepagesize = 2048 kB
size_t len = 3UL << 21;                     // 6 MiB = 3 huge pages
char *p = mmap(NULL, len, PROT_READ | PROT_WRITE,
               MAP_PRIVATE | MAP_ANONYMOUS | MAP_HUGETLB,
               -1, 0);
p[0] = 1;                                   // first touch: page 1
memset(p, 0, len);                          // touch pages 2 and 3
char *q = mmap(NULL, 6UL << 21, PROT_READ | PROT_WRITE,
               MAP_PRIVATE | MAP_ANONYMOUS | MAP_HUGETLB,
               -1, 0);
munmap(p, len);
